function validate([nums1, nums2]) {
  for (const [name, list] of [['nums1', nums1], ['nums2', nums2]]) {
    if (!Array.isArray(list) || list.length < 1 || list.length > 200) return `${name} needs 1 to 200 pairs.`;
    for (let i = 0; i < list.length; i++) {
      const pair = list[i];
      if (!Array.isArray(pair) || pair.length !== 2) return `Each entry of ${name} is a pair [id, val].`;
      if (pair.some(v => !Number.isInteger(v) || v < 1 || v > 1000)) return 'Ids and values are between 1 and 1000.';
      if (i > 0 && list[i - 1][0] >= pair[0]) return `The ids of ${name} must be strictly increasing.`;
    }
  }
  return null;
}

