function mergeArrays(nums1, nums2) {
  const totals = new Map();
  for (const [id, val] of [...nums1, ...nums2]) totals.set(id, (totals.get(id) ?? 0) + val);
  return [...totals.keys()].sort((a, b) => a - b).map(id => [id, totals.get(id)]);
}

