function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const maxId = large ? 1000 : [5, 12, 1000][int(0, 2)];
  const maxVal = rand() < 0.5 ? 1000 : 9;
  const pick = () => {
    const count = large ? int(150, 200) : int(1, Math.min(6, maxId));
    const ids = new Set();
    while (ids.size < count) ids.add(int(1, maxId));
    return [...ids].sort((a, b) => a - b).map(id => [id, int(1, maxVal)]);
  };
  return [pick(), pick()];
}
